"""One place for the data/infra topic classification used by the model
(joins, polled-msg), the viewer and the analysis scripts.  Previously each
importer carried its own fallback list; model_improved_pg's fallback had
five entries, so /diagnostics and */debug/* counted as data (spurious joins).

Override/extend the list via FISH_INFRA_TOPICS (comma-separated globs)."""
import fnmatch as _fnmatch
import os

INFRA_TOPIC_GLOBS = [
    # ROS 2 plumbing
    '/tf', '/tf_static',
    '/parameter_events', '/clock', '/rosout', '/service_log',
    '/*/describe_parameters', '/*/get_parameters', '/*/get_parameter_types',
    '/*/list_parameters', '/*/set_parameters', '/*/set_parameters_atomically',
    # diagnostics / statistics (rqt_graph "Debug" quiet list: /clock /rosout
    # /statistics /diag_agg /time — see rqt_graph/dotcode.py QUIET_NAMES)
    '/diagnostics', '/diagnostics_agg', '/diagnostics_toplevel_state',
    '/statistics', '/time', '/diag_agg',
    # Autoware debug / timing side channels
    '*/debug/*', '*/processing_time_ms', '*/processing_time_detail_ms',
    '*/cyclic_time_ms', '*/pipeline_latency_ms',
    # rqt_graph "hidden" convention: last name segment starting with '_'
    # (e.g. /foo/_bar) — internal / hidden topics.
    '*/_*',
]
# Data topics that the hidden-name rule would wrongly swallow. cuda_blackboard (negotiated publisher/subscription):
# the message that TRIGGERS a GPU subscriber travels on <topic>/cuda/_cuda_image | _cuda_pointcloud2 (an instance id;
# the payload stays in process memory). Found 2026-10-04 with the cuda_blackboard example: the model had the edge
# (ipc_fifo, 36 flows) and the task extractor dropped it as infra. `_supported_types` (negotiation) stays infra.
DATA_TOPIC_GLOBS = ['*/cuda/_cuda_*']
_env_globs = os.environ.get('FISH_INFRA_TOPICS')
if _env_globs:
    INFRA_TOPIC_GLOBS = [g.strip() for g in _env_globs.split(',') if g.strip()]


def topic_class(topic: str) -> str:
    """'infra' for ROS 2 plumbing / diagnostics topics, else 'data'."""
    if not topic:
        return 'data'
    for g in DATA_TOPIC_GLOBS:
        if _fnmatch.fnmatchcase(topic, g):
            return 'data'
    for g in INFRA_TOPIC_GLOBS:
        if _fnmatch.fnmatchcase(topic, g):
            return 'infra'
    return 'data'
